let activeLanguage = 'en';
let localizationObserver = null;
let localizationDirectMap = new Map();
let localizationTemplates = [];

function getSavedLanguage() {
  try {
    const value = localStorage.getItem(LANGUAGE_STORAGE_KEY) || '';
    return Object.prototype.hasOwnProperty.call(SUPPORTED_LANGUAGES, value) ? value : '';
  } catch (err) { return ''; }
}

function saveLanguage(language) {
  if (!Object.prototype.hasOwnProperty.call(SUPPORTED_LANGUAGES, language)) return;
  try { localStorage.setItem(LANGUAGE_STORAGE_KEY, language); } catch (err) {}
}

function escapeLocalizationRegex(value) {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function addLocalizationPair(source, translated) {
  if (!source || !translated || source === translated) return;
  localizationDirectMap.set(source, translated);
  if (!source.includes('${')) return;
  const names = [...source.matchAll(/\$\{([^}]+)\}/g)].map(match => match[1]);
  const parts = source.split(/\$\{[^}]+\}/g).map(escapeLocalizationRegex);
  const pattern = new RegExp(`^${parts.join('(.+?)')}$`, 's');
  localizationTemplates.push({ pattern, translated, names });
}

function buildLocalizationMaps(language) {
  localizationDirectMap = new Map();
  localizationTemplates = [];
  if (language === 'en') return;
  const source = LOCALIZATION_CATALOGS.en;
  const target = LOCALIZATION_CATALOGS[language];
  if (!source || !target) return;
  const pair = (a, b) => addLocalizationPair(String(a || ''), String(b || ''));
  // Hand-reviewed runtime templates take precedence over broad extracted
  // templates. This prevents a generic machine-translated pattern from
  // swallowing a more precise message such as the upgrade price button.
  Object.entries(LOCALIZATION_BOOTSTRAP_TEXT[language] || {}).forEach(([english, translated]) => pair(english, translated));
  Object.keys(source.cards).forEach(id => {
    const a = source.cards[id], b = target.cards[id];
    if (!a || !b) return;
    pair(a.name, b.name); pair(a.faceDescription, b.faceDescription);
    pair(a.rarity, b.rarity); pair(a.baseEffect, b.baseEffect);
    pair(a.howToPlay, b.howToPlay); pair(a.boardPrompt, b.boardPrompt);
    a.upgrades.forEach((value, index) => pair(value, b.upgrades[index]));
  });
  source.tutorials.newRun.forEach((step, index) => pair(step.text, target.tutorials.newRun[index]?.text));
  source.tutorials.puzzle.forEach((step, index) => pair(step.text, target.tutorials.puzzle[index]?.text));
  source.interface.staticText.forEach((value, index) => pair(value, target.interface.staticText[index]));
  source.interface.attributes.forEach((value, index) => pair(value, target.interface.attributes[index]));
  source.interface.runtimePhrases.forEach((entry, index) => pair(entry.text, target.interface.runtimePhrases[index]?.text));
}

function translateGameText(value) {
  if (activeLanguage === 'en' || typeof value !== 'string' || !value.trim()) return value;
  const leading = value.match(/^\s*/)?.[0] || '';
  const trailing = value.match(/\s*$/)?.[0] || '';
  const core = value.slice(leading.length, value.length - trailing.length);
  const direct = localizationDirectMap.get(core);
  if (direct) return leading + direct + trailing;
  for (const item of localizationTemplates) {
    const match = core.match(item.pattern);
    if (!match) continue;
    let translated = item.translated;
    item.names.forEach((name, index) => { translated = translated.replaceAll(`\${${name}}`, match[index + 1]); });
    return leading + translated + trailing;
  }
  return value;
}

function localizeElement(root) {
  if (!root) return;
  const visit = node => {
    if (node.nodeType === Node.TEXT_NODE) {
      const translated = translateGameText(node.nodeValue);
      if (translated !== node.nodeValue) node.nodeValue = translated;
      return;
    }
    if (node.nodeType !== Node.ELEMENT_NODE) return;
    // Script/style contents can contain the entire embedded game and media.
    // They are code, never player-facing copy; walking them would also make
    // localization catastrophically slow in the 100+ MB standalone build.
    if (node.tagName === 'SCRIPT' || node.tagName === 'STYLE') return;
    ['placeholder', 'aria-label', 'title'].forEach(attribute => {
      if (!node.hasAttribute(attribute)) return;
      const value = node.getAttribute(attribute);
      const translated = translateGameText(value);
      if (translated !== value) node.setAttribute(attribute, translated);
    });
    node.childNodes.forEach(visit);
  };
  visit(root);
}

function applyGameDataLocalization(language) {
  const catalog = LOCALIZATION_CATALOGS[language] || LOCALIZATION_CATALOGS.en;
  // The editable template intentionally has no embedded catalogs. Its game
  // data is already English, so there is nothing to apply in that case.
  if (!catalog) return;
  Object.entries(catalog.cards).forEach(([id, card]) => {
    if (CARD_DEFS[id]) { CARD_DEFS[id].name = card.name; CARD_DEFS[id].desc = card.faceDescription; }
    if (CARD_BASE_EFFECTS[id] !== undefined) CARD_BASE_EFFECTS[id] = card.baseEffect;
    if (CARD_PLAY_INSTRUCTIONS[id] !== undefined) CARD_PLAY_INSTRUCTIONS[id] = card.howToPlay;
    if (CARD_BOARD_PROMPTS[id] !== undefined && card.boardPrompt) CARD_BOARD_PROMPTS[id] = card.boardPrompt;
    if (Array.isArray(CARD_MASTERY_TIERS[id])) CARD_MASTERY_TIERS[id].splice(0, CARD_MASTERY_TIERS[id].length, ...card.upgrades);
  });
  catalog.tutorials.newRun.forEach((step, index) => { if (TUTORIAL_STEPS[index]) TUTORIAL_STEPS[index].text = step.text; });
  catalog.tutorials.puzzle.forEach((step, index) => { if (PUZZLE_TUTORIAL_STEPS[index]) PUZZLE_TUTORIAL_STEPS[index].text = step.text; });
}

function applyLocalization(language) {
  activeLanguage = Object.prototype.hasOwnProperty.call(SUPPORTED_LANGUAGES, language) ? language : 'en';
  document.documentElement.lang = activeLanguage;
  buildLocalizationMaps(activeLanguage);
  applyGameDataLocalization(activeLanguage);
  localizeElement(document.body);
  if (localizationObserver) localizationObserver.disconnect();
  localizationObserver = new MutationObserver(records => records.forEach(record => {
    record.addedNodes.forEach(localizeElement);
  }));
  // textContent/innerHTML updates replace or add text nodes and therefore
  // arrive as child-list mutations. Watching our own character-data edits can
  // create translation cycles in languages whose translated word is also an
  // English source key (observed with Japanese upgrade text).
  localizationObserver.observe(document.body, { subtree: true, childList: true });
  const select = document.getElementById('settingsLanguageSelect');
  if (select) select.value = activeLanguage;
}

function chooseInitialLanguage(language) {
  saveLanguage(language);
  location.reload();
}

function openFirstRunLanguageModal() {
  document.getElementById('languageEntryOverlay').classList.add('active');
}

// Keep every player-facing notice and confirmation inside the game. Native
// browser dialogs label themselves with the hosting origin and can expose
// deployment/provider details that the player should never see.
let gameDialogConfirmAction = null;

function showGameDialog(message, options = {}) {
  const overlay = document.getElementById('gameDialogOverlay');
  const title = document.getElementById('gameDialogTitle');
  const body = document.getElementById('gameDialogMessage');
  const confirmButton = document.getElementById('gameDialogConfirmBtn');
  const cancelButton = document.getElementById('gameDialogCancelBtn');
  if (!overlay || !title || !body || !confirmButton || !cancelButton) {
    // Never fall back to a native browser dialog. The ordinary status line
    // is a safe last resort if this custom overlay is unavailable.
    if (typeof setMessage === 'function') setMessage(String(message || ''));
    return;
  }

  title.textContent = String(options.title || 'NOTICE');
  body.textContent = String(message || '');
  confirmButton.textContent = String(options.confirmText || 'OK');
  gameDialogConfirmAction = typeof options.onConfirm === 'function'
    ? options.onConfirm
    : null;

  if (options.cancelText) {
    cancelButton.textContent = String(options.cancelText);
    cancelButton.style.display = '';
  } else {
    cancelButton.style.display = 'none';
  }
  overlay.classList.add('active');
  requestAnimationFrame(() => confirmButton.focus());
}

function dismissGameDialog() {
  const overlay = document.getElementById('gameDialogOverlay');
  if (overlay) overlay.classList.remove('active');
  gameDialogConfirmAction = null;
}

function acceptGameDialog() {
  const action = gameDialogConfirmAction;
  dismissGameDialog();
  if (action) action();
}

// ── PERSISTENT AUDIO SETTINGS ──
// These preferences belong to the whole installation, not to a particular
// run or mode. The 100% slider position preserves the existing menu/gameplay
// mix; lower positions scale both music channels together.
const AUDIO_SETTINGS_STORAGE_KEY = 'kingMeAudioSettingsV1';
const DEFAULT_AUDIO_SETTINGS = Object.freeze({
  musicEnabled: true,
  sfxEnabled: true,
  musicVolume: 1
});

function loadAudioSettings() {
  try {
    const saved = JSON.parse(localStorage.getItem(AUDIO_SETTINGS_STORAGE_KEY) || 'null');
    return {
      musicEnabled: saved?.musicEnabled !== false,
      sfxEnabled: saved?.sfxEnabled !== false,
      musicVolume: Math.max(0, Math.min(1,
        Number.isFinite(Number(saved?.musicVolume)) ? Number(saved.musicVolume) : 1
      ))
    };
  } catch (err) {
    return { ...DEFAULT_AUDIO_SETTINGS };
  }
}

let audioSettings = loadAudioSettings();

function saveAudioSettings() {
  try {
    localStorage.setItem(AUDIO_SETTINGS_STORAGE_KEY, JSON.stringify(audioSettings));
  } catch (err) {}
}

function updateAudioSettingsUI() {
  const musicToggle = document.getElementById('settingsMusicToggle');
  const sfxToggle = document.getElementById('settingsSfxToggle');
  const volumeSlider = document.getElementById('musicVolumeSlider');
  const volumeValue = document.getElementById('musicVolumeValue');
  if (musicToggle) {
    musicToggle.textContent = audioSettings.musicEnabled ? 'On' : 'Off';
    musicToggle.setAttribute('aria-pressed', String(audioSettings.musicEnabled));
  }
  if (sfxToggle) {
    sfxToggle.textContent = audioSettings.sfxEnabled ? 'On' : 'Off';
    sfxToggle.setAttribute('aria-pressed', String(audioSettings.sfxEnabled));
  }
  const percent = Math.round(audioSettings.musicVolume * 100);
  if (volumeSlider) valueIfDifferent(volumeSlider, String(percent));
  if (volumeValue) volumeValue.textContent = `${percent}%`;
}

function valueIfDifferent(input, value) {
  if (input.value !== value) input.value = value;
}

function applyAudioSettings(resumeMusic = true) {
  // Keep the legacy saved field synchronized for the handful of procedural
  // sounds that check it directly, while the global setting remains the
  // single source of truth.
  if (typeof state !== 'undefined' && state) state.sfxMuted = !audioSettings.sfxEnabled;
  applySfxMuteFromState();
  if (mainMenuMusic) mainMenuMusic.volume = MUSIC_VOLUME * audioSettings.musicVolume;
  if (gameplayMusic) gameplayMusic.volume = GAMEPLAY_MUSIC_VOLUME * audioSettings.musicVolume;
  if (!audioSettings.musicEnabled || audioSettings.musicVolume <= 0) {
    pauseMenuMusic();
    pauseGameplayMusic();
  } else if (resumeMusic) {
    syncBackgroundMusicForCurrentScreen();
  }
  updateAudioSettingsUI();
}

function openSettings() {
  updateAudioSettingsUI();
  document.getElementById('settingsOverlay').classList.add('active');
}

function closeSettings() {
  document.getElementById('settingsOverlay').classList.remove('active');
}

// ── SOUND EFFECTS ──
// STANDING RULE (explicitly requested — do not quietly deviate from this):
// every sound EFFECT in the game (the landing sound below, and every one of
// the ~80 planned card/menu-click sounds still to come) must play at exactly
// SFX_VOLUME, never its own one-off number. The whole point is that no
// single effect should ever sound louder or quieter than any other — when
// wiring up a new sound, set `.volume = SFX_VOLUME` and otherwise leave it
// alone rather than tuning it per-sound. Background music is intentionally
// a separate channel (see MUSIC_VOLUME below near the main menu music) since
// music and foreground SFX conventionally sit at different relative levels
// in a mix — but every individual SFX must match every other SFX exactly.
//
// Also worth remembering for whoever records/exports those future sound
// files: setting the same `.volume` here only controls playback level in the
// browser — it can't fix two source recordings that were captured/mastered
// at different loudness to begin with. Loudness-normalizing every sound
// file during export (e.g. `ffmpeg ... -filter:a loudnorm`) to a consistent
// target before it ever gets embedded is what actually guarantees they all
// sound equally loud, not just equally multiplied.
// `let`, not `const` — the new run-start sound-effects on/off toggle works
// by reassigning this shared variable (see applySfxMuteFromState below)
// rather than touching every individual playXSound() function. Every one
// of those functions reads SFX_VOLUME fresh at the moment a sound actually
// plays, so flipping this one value instantly mutes/unmutes all of them.
let SFX_VOLUME = 0.6;

// Reuse decoded audio so embedded WAV parsing never sits on the click path.
const SFX_AUDIO_POOLS = new Map();
function getCachedSfx(url) {
  let pool = SFX_AUDIO_POOLS.get(url);
  if (!pool) {
    const audio = new Audio();
    audio.preload = 'auto';
    audio.src = url;
    audio.load();
    pool = [audio];
    SFX_AUDIO_POOLS.set(url, pool);
  }
  let audio = pool.find(item => item.paused || item.ended);
  if (!audio) {
    audio = pool[0].cloneNode(true);
    pool.push(audio);
  }
  try { audio.currentTime = 0; } catch (err) {}
  return audio;
}
function playCachedSfx(url, volume = SFX_VOLUME) {
  try {
    const audio = getCachedSfx(url);
    audio.volume = volume;
    const playback = audio.play();
    if (playback && typeof playback.catch === 'function') playback.catch(() => {});
  } catch (err) {}
}
const SFX_VOLUME_ON = 0.6; // the real "on" level — restored when unmuting

// Applies state.sfxMuted (set from the run-start toggle, persisted for the
// whole run same as any other state field, and reset back to false whenever
// a run ends via triggerLose — see there) to the actual SFX_VOLUME every
// playXSound() function reads. Call this any time state.sfxMuted changes:
// right after a new run starts, right after a saved run is resumed, and
// right when a run ends.
function applySfxMuteFromState() {
  SFX_VOLUME = audioSettings.sfxEnabled ? SFX_VOLUME_ON : 0;
}

// Plain-movement landing sound: plays only for a normal move/capture the
// PLAYER makes with their own piece (getValidMoves tags these `plainMovement:
// true` — see executeMove). Deliberately does NOT play for any card/ability-
// driven move (Teleport, Side Step, a charge, Catapult, War Horse, etc.),
// and never for the enemy AI, which has its own separate move path
// (actOnePiece) that never touches executeMove at all.
const LOCUST_SWARM_SOUND_URL = 'data:audio/wav;base64,';
const BLACK_HOLE_SOUND_URL = 'data:audio/wav;base64,';
const TIDAL_WAVE_SOUND_URL = 'data:audio/wav;base64,';
const PIECE_LAND_SOUND_URL = 'data:audio/wav;base64,';
let pieceMoveAudioContext = null;
let pieceMoveNoiseBuffer = null;
function playPieceLandSound() {
  try {
    const AudioContextClass = window.AudioContext || window.webkitAudioContext;
    if (!AudioContextClass || SFX_VOLUME <= 0) return;
    pieceMoveAudioContext = pieceMoveAudioContext || new AudioContextClass();
    const ctx = pieceMoveAudioContext;
    const playUnlocked = () => {
      // A short, low wooden contact sound made only from filtered noise. The
      // former sample contained a light pitched chirp after the piece landed;
      // avoiding oscillators (and the old sample) leaves only the checker move.
      if (!pieceMoveNoiseBuffer || pieceMoveNoiseBuffer.sampleRate !== ctx.sampleRate) {
        const length = Math.max(1, Math.floor(ctx.sampleRate * .105));
        pieceMoveNoiseBuffer = ctx.createBuffer(1, length, ctx.sampleRate);
        const data = pieceMoveNoiseBuffer.getChannelData(0);
        let smoothed = 0;
        for (let i = 0; i < length; i++) {
          smoothed = smoothed * .78 + (Math.random() * 2 - 1) * .22;
          data[i] = smoothed * Math.pow(1 - i / length, 2.4);
        }
      }
      const source = ctx.createBufferSource();
      const filter = ctx.createBiquadFilter();
      const gain = ctx.createGain();
      source.buffer = pieceMoveNoiseBuffer;
      filter.type = 'lowpass';
      filter.frequency.value = 720;
      filter.Q.value = .45;
      const now = ctx.currentTime;
      gain.gain.setValueAtTime(Math.max(.0001, SFX_VOLUME * .28), now);
      gain.gain.exponentialRampToValueAtTime(.0001, now + .105);
      source.connect(filter);
      filter.connect(gain);
      gain.connect(ctx.destination);
      source.start(now);
      source.stop(now + .11);
    };

    // Android WebView commonly begins with a suspended AudioContext. Starting
    // the source before resume() finishes silently drops the movement sound,
    // so wait for the context to be live before scheduling it.
    if (ctx.state === 'suspended') {
      ctx.resume().then(playUnlocked).catch(() => {});
    } else {
      playUnlocked();
    }
  } catch (err) {
    // Never let a sound-effect failure interrupt the actual game logic.
  }
}

// Generic UI click — plays for any button/control click, in-game or not:
// the main menu, level select, name entry, the leaderboard, the card
// collection, the enlarged-card view, AND, inside
// actual gameplay, the card stacks, the carousel cards, Menu, Forfeit, End
// Turn, and the tutorial banner's Next button — every clickable
// control except the board itself. Deliberately a single document-level
// delegated listener rather than one per button, so every current AND
// future control gets this for free with nothing to wire up by hand and
// nothing to forget when new buttons get added later. #board is the one
// and only exclusion — actual piece moves have their own feedback
// (playPieceLandSound for plain movement, card-specific sounds for
// ability-driven moves, or silence), and shouldn't ALSO get a generic
// click on top of that.
const UI_CLICK_SOUND_URL = 'data:audio/wav;base64,';
function playUIClickSound() {
  try {
    const sfx = getCachedSfx(UI_CLICK_SOUND_URL);
    sfx.volume = SFX_VOLUME; // standing rule — every SFX shares this one level
    sfx.play().catch(() => {});
  } catch (err) {
    // Never let a sound-effect failure interrupt the actual game logic.
  }
}
function initUIClickSound() {
  // MUST be a capture-phase listener (the trailing `true`), not the default
  // bubble phase. A board-cell click's OWN handler (initBoardClickDelegation,
  // attached on #board, bubble phase — see there) runs cellClick() ->
  // render(), which does `boardEl.innerHTML = ''` and rebuilds the board
  // SYNCHRONOUSLY, before the event ever finishes bubbling up to document.
  // That detaches the original clicked .cell from the DOM tree mid-bubble —
  // and `.closest()` on an already-detached node can only search its own
  // orphaned subtree, so by the time a bubble-phase listener here would run,
  // `e.target.closest('#board')` would no longer find #board at all (it's
  // not an ancestor of the orphaned node anymore) and incorrectly fall
  // through to playing the UI click sound during real board taps. Capture
  // phase runs on the way DOWN, before #board's bubble-phase handler gets a
  // chance to tear anything down, so the ancestry check always sees the
  // pre-click, still-attached DOM.
  document.addEventListener('click', (e) => {
    if (e.target.closest('#board')) return; // board taps have their own sound feedback (or intentionally none)
    playUIClickSound();
    const menuVisible = document.getElementById('mainMenu')?.classList.contains('active')
      || document.getElementById('puzzleMenu')?.classList.contains('active');
    if (menuVisible) playMenuMusic();
  }, true);
}

