// ── BACKGROUND MUSIC CHANNELS ──
// Drop finished gameplay tracks into assets/music using the filenames mapped
// by embed_assets.ps1. Gameplay uses the source files' full mixed volume.
// embed_assets.ps1 replaces the slot tokens with embedded audio data whenever
// those files exist. Missing slots become empty strings and are ignored, so
// this build remains fully functional before the music files are delivered.
const MUSIC_VOLUME = 0.18;
const GAMEPLAY_MUSIC_VOLUME = 1;
const GAMEPLAY_MUSIC_TRACKS = Object.freeze([
  'gameplay1.wav',
  'gameplay2.wav'
]);

let mainMenuMusic = null;
let gameplayMusic = null;
let gameplayMusicIndex = -1;

function playMenuMusic() {
  try {
    pauseGameplayMusic();
    // Tutorials are intentionally silent, even during their menu/collection
    // teaching steps. They may temporarily show a menu without actually
    // leaving the tutorial, so screen visibility alone is not enough here.
    if (typeof tutorial !== 'undefined' && tutorial.active) {
      pauseMenuMusic();
      return;
    }
    if (!audioSettings.musicEnabled || audioSettings.musicVolume <= 0) return;
    if (!mainMenuMusic) {
      mainMenuMusic = new Audio(MENU_MUSIC_URL);
      mainMenuMusic.loop = true;
      mainMenuMusic.volume = MUSIC_VOLUME * audioSettings.musicVolume;
      mainMenuMusic.preload = 'auto';
    }
    mainMenuMusic.volume = MUSIC_VOLUME * audioSettings.musicVolume;
    const playback = mainMenuMusic.play();
    if (playback && typeof playback.catch === 'function') playback.catch(() => {});
  } catch (err) {}
}

function pauseMenuMusic() {
  if (mainMenuMusic) mainMenuMusic.pause();
}

function loadGameplayMusicTrack(index) {
  if (!GAMEPLAY_MUSIC_TRACKS.length) return false;
  if (!gameplayMusic) {
    gameplayMusic = new Audio();
    gameplayMusic.preload = 'auto';
    gameplayMusic.volume = GAMEPLAY_MUSIC_VOLUME * audioSettings.musicVolume;
    gameplayMusic.addEventListener('ended', () => {
      if (!GAMEPLAY_MUSIC_TRACKS.length || !audioSettings.musicEnabled || audioSettings.musicVolume <= 0) return;
      loadGameplayMusicTrack(getRandomGameplayMusicIndex());
      const playback = gameplayMusic.play();
      if (playback && typeof playback.catch === 'function') playback.catch(() => {});
    });
  }
  const nextIndex = ((index % GAMEPLAY_MUSIC_TRACKS.length) + GAMEPLAY_MUSIC_TRACKS.length)
    % GAMEPLAY_MUSIC_TRACKS.length;
  if (gameplayMusicIndex !== nextIndex || !gameplayMusic.src) {
    gameplayMusicIndex = nextIndex;
    gameplayMusic.src = GAMEPLAY_MUSIC_TRACKS[nextIndex];
    gameplayMusic.loop = GAMEPLAY_MUSIC_TRACKS.length === 1;
    gameplayMusic.load();
  }
  return true;
}

function getRandomGameplayMusicIndex() {
  if (GAMEPLAY_MUSIC_TRACKS.length <= 1) return 0;
  let nextIndex = gameplayMusicIndex;
  while (nextIndex === gameplayMusicIndex) {
    nextIndex = Math.floor(Math.random() * GAMEPLAY_MUSIC_TRACKS.length);
  }
  return nextIndex;
}

function playGameplayMusic() {
  try {
    // Gameplay music belongs only to a real run. Both tutorials use the live
    // board engine, but must remain completely music-free.
    if (typeof tutorial !== 'undefined' && tutorial.active) {
      pauseMenuMusic();
      pauseGameplayMusic();
      return;
    }
    // Always stop the menu channel before checking whether gameplay tracks
    // are available. This prevents menu music leaking into gameplay in a
    // build where a gameplay asset is absent or still loading.
    pauseMenuMusic();
    if (!GAMEPLAY_MUSIC_TRACKS.length || !audioSettings.musicEnabled || audioSettings.musicVolume <= 0) return;
    if (!gameplayMusic || gameplayMusicIndex < 0) {
      loadGameplayMusicTrack(getRandomGameplayMusicIndex());
    }
    gameplayMusic.volume = GAMEPLAY_MUSIC_VOLUME * audioSettings.musicVolume;
    const playback = gameplayMusic.play();
    if (playback && typeof playback.catch === 'function') playback.catch(() => {});
  } catch (err) {}
}

function pauseGameplayMusic() {
  if (gameplayMusic) gameplayMusic.pause();
}

function syncBackgroundMusicForCurrentScreen() {
  if (document.hidden) return;
  if (typeof tutorial !== 'undefined' && tutorial.active) {
    pauseMenuMusic();
    pauseGameplayMusic();
    return;
  }
  const menuVisible = document.getElementById('mainMenu')?.classList.contains('active')
    || document.getElementById('puzzleMenu')?.classList.contains('active');
  const gameplayVisible = document.getElementById('gameApp')?.style.display !== 'none';
  if (menuVisible || (state && state.gameOver)) {
    playMenuMusic();
  } else if (gameplayVisible) {
    playGameplayMusic();
  }
}

